import time
from SSHLibrary import SSHLibrary
from SSHLibrary.pythonclient import PythonSSHClient
import re

try:
    mod = __import__("version", globals())
    __version__ = mod.version
except Exception:
    __version__ = "0.0.0"


class SSHClientChild(PythonSSHClient):
    def read_until(self, expected):
        return self._read_until(lambda s: re.search(expected, s), expected)


class MySshLib(SSHLibrary):
    def __init__(self, timeout=3, newline='LF', prompt=None):
        SSHLibrary.__init__(self, timeout, newline, prompt)
        self.type = "SSH"

    def open_connection(self, host, alias=None, port=22, timeout=None,
                        newline=None, prompt=None, term_type=None, width=None,
                        height=None, path_separator=None, encoding=None):
        timeout = timeout or self._config.timeout
        newline = newline or self._config.newline
        prompt = prompt or self._config.prompt
        term_type = term_type or self._config.term_type
        width = width or self._config.width
        height = height or self._config.height
        path_separator = path_separator or self._config.path_separator
        encoding = encoding or self._config.encoding
        client = SSHClientChild(host, alias, port, timeout, newline, prompt,
                                term_type, width, height, path_separator, encoding)
        connection_index = self._connections.register(client, alias)
        client.config.update(index=connection_index)
        return connection_index

    def get_transport(self):
        return self.current.client.get_transport()

    @property
    def _prompt(self):
        return self.current.config.prompt

    @_prompt.setter
    def _prompt(self, new_prompt):
        old_prompt = self._prompt
        self.current.config.update(prompt=new_prompt)
        return old_prompt

    def set_timeout(self, new_timeout):
        old_timeout = self.current.config.timeout
        self.current.config.update(timeout=new_timeout)
        return old_timeout


class SshConnection:
    def __init__(self):
        self.ssh_pool = {}

    def connect_to_ssh_host(self, host, port=22, user="omc", passwd="omc",
                            prompt="", timeout="60sec", keyfile="",
                            width=None):
        if prompt is None or prompt == "":
            myprompt = r"\[.*?@.*?\]\s*#"
        else:
            myprompt = prompt
        conn = MySshLib(timeout, "CR", myprompt)
        conn.open_connection(host, port=port, width=width)
        if keyfile:
            conn.login_with_public_key(user, keyfile, passwd)
        else:
            conn.login(user, passwd)
        return conn

    def connect_to(self, ip, username, password, port=22, prompt="",
                   timeout="60s", width=None, alias=None, keyfile=""):
        """
        author: jinbo.yu@nokia-sbell.com
        history change, <date>,<who>,<what and how>
        -7.07.2020,chris.l.cao@nokia-sbell.com,
                   Fails if the given alias is duplicated.
         """
        if not alias:
            alias = str(time.time()).replace(".", "")
        if alias in self.ssh_pool.keys():
            raise RuntimeError("This alias:{} already existed".format(alias))
        conn = self.connect_to_ssh_host(ip, port=port, user=username,
                                        passwd=password, prompt=prompt,
                                        timeout=timeout, width=width,
                                        keyfile=keyfile)
        self.ssh_pool[alias] = conn
        return alias
